function straightLine(cost, salvage, life){ cost=+cost; salvage=+salvage; life=+life; if(!(life>0)) return {error:'年限须为正'};
  var a=(cost-salvage)/life; return {annual:Math.round(a*100)/100, bookEnd:salvage}; }
function declining(cost, life, rate, years){ cost=+cost; life=+life; rate=rate==null?2/life:rate; years=years||life;
  var sched=[]; var b=cost; for(var y=1;y<=years;y++){ var d=b*rate; if(y>life) d=0; sched.push(Math.round(d*100)/100); b-=d; } return sched; }
function sumOfYears(cost, salvage, life){ cost=+cost; salvage=+salvage; life=+life; if(!(life>0)) return {error:'年限须为正'};
  var sum=life*(life+1)/2; var sched=[]; for(var y=1;y<=life;y++){ var d=(cost-salvage)*(life-y+1)/sum; sched.push(Math.round(d*100)/100); } return sched; }
var EXPORTS={straightLine:straightLine, declining:declining, sumOfYears:sumOfYears};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DepreciationForgePure = EXPORTS; }
